\label{prop:not-frechet}
 $Y=(E,\tau_c)$ defined by (\ref{eq:Y-E}) is not a
Fr\'echet--Urysohn space. Furthermore, $Y$ is not first countable.

\label{thm:main-example}
There exists a countable, second-countable, Hausdorff, semiregular
quasitopological abelian group $G$ whose continuous real-valued
functions separate points such that
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=*]
\item the canonical maps to $\operatorname{Reg}(G)$ and $\operatorname{Tych}(G)$ are bijective;
\item $\operatorname{Reg}(G)$ and $\operatorname{Tych}(G)$ are canonically topologically isomorphic;
\item $\operatorname{Reg}(G)$ and $\operatorname{Tych}(G)$ are countable, zero-dimensional
quasitopological groups that are not Fr\'echet--Urysohn.
\end{enumerate}
Consequently, neither first countability nor second countability is
preserved by the regular or Tychonoff reflection, even for countable
Hausdorff quasitopological abelian groups.

\label{cor:nonquotient}
In Theorem~\ref{thm:main-example}, neither canonical reflection map
is quotient, open, or $d$-open.

\label{lem:universal-function}
For every nonempty countable first-countable space $X$, there are a
Polish abelian topological group $B$ and $F\in C(X\times B,[0,1])$
such that
\begin{equation}\label{eq:all-slices}
          \{F(\,\cdot\,,b):b\in B\}=C(X,[0,1]).
\end{equation}
One may take $B=\mathbb{R}^X\times\mathbb Z^{X\times\mathbb{N}}$ with its product
group topology, where $\mathbb Z$ is discrete.

\label{cor:66-67}
For every quasitopological group $G$, without any separation
assumption, one has
\begin{align*}
 G\text{ is }(\mathbb{R},\mathbb{FCSG})\text{-factorizable}
 &\ \Longleftrightarrow\
 G\text{ is }(\mathbb{R},\mathbb{FCQG})\text{-factorizable},\\
 G\text{ is }(\mathbb{R},\mathbb{SCSG})\text{-factorizable}
 &\ \Longleftrightarrow\
 G\text{ is }(\mathbb{R},\mathbb{SCQG})\text{-factorizable}.
\end{align*}
Thus Problems~6.6 and~6.7 of~\cite{Tk2026} have affirmative answers.
